mapper.insert:

    SELECT
        'AWAD'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(AWARD_CODE), LENGTH('AWAD' ) + 1)), 0) + 1, 6, '0')
    FROM AWARD

INSERT INTO AWARD (
	AWARD_CODE
	, RESUME_NO
	, AWARD_NAME
	, AWARD_DATE
	, HOSTING
) VALUES (
	#{awardCode}
	, #{resumeNo}
	, #{awardName}
	, REPLACE(#{awardDate}, '-', '')
	, #{hosting}
)

mapper.update:
UPDATE AWARD 
   SET RESUME_NO = #{resumeNo}
   	   , AWARD_NAME = #{awardName}
   	   , AWARD_DATE = REPLACE(#{awardDate}, '-', '')
   	   , HOSTING = #{hosting}
 WHERE AWARD_CODE = #{awardCode}
